module.exports = function(RED) {
    "use strict";
    var util = require("util");
    var vm = require("vm");

    // TypeScript compiler integration
    let typescript;
    try {
        typescript = require('typescript');
    } catch(err) {
        // TypeScript not available - fallback to JavaScript only
        RED.log.warn("TypeScript not available. Install 'typescript' package for TypeScript support.");
    }

    // Zod integration for schema validation
    let zod;
    try {
        zod = require('zod');
    } catch(err) {
        RED.log.warn("Zod not available. Install 'zod' package for schema validation support.");
    }

    function FunctionNode(n) {
        RED.nodes.createNode(this,n);
        var node = this;
        this.name = n.name;
        this.func = n.func;
        this.language = n.language || 'javascript'; // 'javascript' or 'typescript'
        this.compilerOptions = n.compilerOptions || {
            target: 'ES2020',
            module: 'CommonJS',
            strict: false,
            esModuleInterop: true,
            skipLibCheck: true
        };

        var functionText = "var results = null;"+
                           "results = (async function(msg,__send__,__done__){ "+
                               "var __msgid__ = msg._msgid;"+
                               "var node = {"+
                                   "id:__node__.id,"+
                                   "name:__node__.name,"+
                                   "path:__node__.path,"+
                                   "outputCount:__node__.outputCount,"+
                                   "log:__node__.log,"+
                                   "error:__node__.error,"+
                                   "warn:__node__.warn,"+
                                   "debug:__node__.debug,"+
                                   "trace:__node__.trace,"+
                                   "on:__node__.on,"+
                                   "status:__node__.status,"+
                                   "send:function(msgs,cloneMsg){ __node__.send(__send__,__msgid__,msgs,cloneMsg);},"+
                                   "done:__done__"+
                               "};"+
                               "\n"+
                               this.func+"\n"+
                           "})(msg,send,done);";

        // Compile TypeScript if needed
        if (this.language === 'typescript' && typescript) {
            try {
                var compiledJS = this.compileTypeScript(this.func);
                if (compiledJS.success) {
                    // Replace the function body with compiled JavaScript
                    functionText = functionText.replace(this.func, compiledJS.code);
                } else {
                    this.error("TypeScript compilation failed: " + compiledJS.error);
                    return;
                }
            } catch(err) {
                this.error("TypeScript compilation error: " + err.message);
                return;
            }
        }

        var handleNodeDoneCall = true;
        // Check to see if the Function appears to call `node.done()`. If so,
        // we will assume it is well written and does actually call node.done().
        // Otherwise, we will call node.done() after the function returns regardless.
        if (/node\.done\s*\(\s*\)/.test(functionText)) {
            handleNodeDoneCall = false;
        }

        var msgs = [];
        var setupFinished = false;

        if (handleNodeDoneCall) {
            functionText += "return results;"
        }

        this.topic = n.topic;
        this.outstandingTimers = [];
        this.outstandingIntervals = [];
        this.clearStatus = false;

        var sandbox = {
            console:console,
            util:util,
            Buffer:Buffer,
            Date: Date,
            RED: {
                util: RED.util
            },
            __node__: {
                id: node.id,
                name: node.name,
                path: node._path,
                outputCount: node.wires.length,
                log: function() {
                    node.log.apply(node, arguments);
                },
                error: function() {
                    node.error.apply(node, arguments);
                },
                warn: function() {
                    node.warn.apply(node, arguments);
                },
                debug: function() {
                    node.debug.apply(node, arguments);
                },
                trace: function() {
                    node.trace.apply(node, arguments);
                },
                send: function(send, id, msgs, cloneMsg) {
                    if (cloneMsg !== false && msgs) {
                        if (util.isArray(msgs)) {
                            msgs = msgs.map(function(m) {
                                if (m) {
                                    return RED.util.cloneMessage(m);
                                }
                                return m;
                            });
                        } else {
                            msgs = RED.util.cloneMessage(msgs);
                        }
                    }
                    if (send) {
                        send(msgs);
                    } else {
                        node.send(msgs);
                    }
                },
                on: function() {
                    if (arguments[0] === "input") {
                        throw new Error(RED._("function.error.inputListener"));
                    }
                    node.on.apply(node, arguments);
                },
                status: function() {
                    node.status.apply(node, arguments);
                }
            },
            context: {
                set: function() {
                    node.context().set.apply(node,arguments);
                },
                get: function() {
                    return node.context().get.apply(node,arguments);
                },
                keys: function() {
                    return node.context().keys.apply(node,arguments);
                },
                get global() {
                    return node.context().global;
                },
                get flow() {
                    return node.context().flow;
                }
            },
            flow: {
                set: function() {
                    node.context().flow.set.apply(node,arguments);
                },
                get: function() {
                    return node.context().flow.get.apply(node,arguments);
                },
                keys: function() {
                    return node.context().flow.keys.apply(node,arguments);
                }
            },
            global: {
                set: function() {
                    node.context().global.set.apply(node,arguments);
                },
                get: function() {
                    return node.context().global.get.apply(node,arguments);
                },
                keys: function() {
                    return node.context().global.keys.apply(node,arguments);
                }
            },
            env: {
                get: function(envVar) {
                    var flow = node._flow;
                    return flow.getSetting(envVar);
                }
            },
            setTimeout: function () {
                var func = arguments[0];
                var timerId;
                arguments[0] = function() {
                    sandbox.clearTimeout(timerId);
                    try {
                        func.apply(this,arguments);
                    } catch(err) {
                        node.error(err,{});
                    }
                };
                timerId = setTimeout.apply(this,arguments);
                node.outstandingTimers.push(timerId);
                return timerId;
            },
            clearTimeout: function(id) {
                clearTimeout(id);
                var index = node.outstandingTimers.indexOf(id);
                if (index > -1) {
                    node.outstandingTimers.splice(index,1);
                }
            },
            setInterval: function() {
                var func = arguments[0];
                var timerId;
                arguments[0] = function() {
                    try {
                        func.apply(this,arguments);
                    } catch(err) {
                        node.error(err,{});
                    }
                };
                timerId = setInterval.apply(this,arguments);
                node.outstandingIntervals.push(timerId);
                return timerId;
            },
            clearInterval: function(id) {
                clearInterval(id);
                var index = node.outstandingIntervals.indexOf(id);
                if (index > -1) {
                    node.outstandingIntervals.splice(index,1);
                }
            }
        };

        // Add Zod to sandbox if available
        if (zod) {
            sandbox.z = zod;
            sandbox.zod = zod;
        }

        // Add custom module loader for Node-RED scripts
        sandbox.require = function(moduleName) {
            if (moduleName.startsWith('@node-red/scripts/')) {
                return node.loadNodeRedScript(moduleName);
            }
            // For other modules, return standard require or throw error
            try {
                return require(moduleName);
            } catch(err) {
                throw new Error("Module '" + moduleName + "' not available in function context");
            }
        };

        if (util.hasUncaughtExceptionCaptureCallback && util.hasUncaughtExceptionCaptureCallback()) {
            // If the process has an uncaught exception handler installed, use that.
            // This prevents unwanted calls to process.exit()
            sandbox.process = process;
        } else {
            // Create a minimal process object to satisfy some library requirements
            sandbox.process = {
                env: process.env,
                versions: process.versions
            }
        }

        var context = vm.createContext(sandbox);
        try {
            this.script = vm.createScript(functionText, {
                filename: 'Function node:'+this.id+(this.name?' ['+this.name+']':''), // filename for stack traces
                displayErrors: true
            });
            this.on("input", function(msg,send,done) {
                try {
                    var start = process.hrtime();
                    context.msg = msg;
                    context.send = send;
                    context.done = done;

                    this.script.runInContext(context);
                    var results = context.results;

                    if (handleNodeDoneCall) {
                        if (results == null) {
                            results = [];
                        } else if (results.length == null) {
                            results = [results];
                        }
                        if (results.length > node.wires.length) {
                            results = results.slice(0,node.wires.length);
                        }
                    }
                    var duration = process.hrtime(start);
                    var converted = Math.floor((duration[0] * 1e9 + duration[1])/10000)/100;
                    this.metric("duration", msg, converted);
                    if (handleNodeDoneCall) {
                        send(results);
                        done();
                    }

                } catch(err) {
                    if ((typeof err === "object") && err.hasOwnProperty("stack")) {
                        //remove unwanted part
                        var index = err.stack.search(/\n\s*at ContextifyScript.Script.runInContext/);
                        err.stack = err.stack.substring(0, index).split('\n').slice(0,-1).join('\n');
                        var stack = err.stack.split(/\r?\n/);
                        if (stack.length > 0) {
                            while (stack.length > 0 && stack[0].indexOf("ReferenceError") !== 0) {
                                stack.shift();
                            }
                            if (stack.length > 0) {
                                err.message = stack.shift();
                                err.stack = stack.join('\n');
                            }
                        }
                    }
                    done(err);
                }
            });
            this.on("close", function() {
                while(node.outstandingTimers.length > 0) {
                    clearTimeout(node.outstandingTimers.pop());
                }
                while(node.outstandingIntervals.length > 0) {
                    clearInterval(node.outstandingIntervals.pop());
                }
                this.status({});
            });
        } catch(err) {
            // eg SyntaxError - which v8 doesn't include line number information
            // so we can't do better than throw a generic error
            this.error(err);
        }
    }

    // TypeScript compilation method
    FunctionNode.prototype.compileTypeScript = function(tsCode) {
        if (!typescript) {
            return { success: false, error: "TypeScript compiler not available" };
        }

        try {
            // TypeScript compiler options
            const compilerOptions = {
                target: typescript.ScriptTarget.ES2020,
                module: typescript.ModuleKind.CommonJS,
                strict: false,
                esModuleInterop: true,
                skipLibCheck: true,
                allowJs: true,
                ...this.compilerOptions
            };

            // Compile TypeScript to JavaScript
            const result = typescript.transpile(tsCode, compilerOptions);
            
            return { success: true, code: result };
        } catch (error) {
            return { success: false, error: error.message };
        }
    };

    // Load Node-RED script modules
    FunctionNode.prototype.loadNodeRedScript = function(moduleName) {
        // This would load scripts from a predefined scripts directory
        // For now, return a placeholder that can be extended
        var scriptPath = moduleName.replace('@node-red/scripts/', '');
        
        // In a real implementation, this would:
        // 1. Look up the script in the scripts directory
        // 2. Compile it if it's TypeScript
        // 3. Cache the compiled result
        // 4. Return the exported functions/objects
        
        throw new Error("Script module '" + moduleName + "' not found");
    };

    RED.nodes.registerType("function",FunctionNode);
    RED.library.register("functions");
}